#!/usr/bin/env python3
import sys

def int_to_roman(num):
    val = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
    syms = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"]
    roman_num = ''
    i = 0
    while num > 0:
        for _ in range(num // val[i]):
            roman_num += syms[i]
            num -= val[i]
        i += 1
    return roman_num

def roman_to_int(s):
    roman = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    prev_value = 0
    total = 0
    for char in reversed(s):
        value = roman.get(char, 0)
        if value < prev_value:
            total -= value
        else:
            total += value
        prev_value = value
    return total

def main():
    if len(sys.argv) < 3:
        print("Usage: roman.py [to-roman|from-roman] <number|numeral>")
        sys.exit(1)

    mode = sys.argv[1]
    value = sys.argv[2]

    if mode == 'to-roman':
        try:
            num = int(value)
            if not (0 < num < 4000):
                print("Number out of range (must be 1..3999)")
                sys.exit(1)
            print(int_to_roman(num))
        except ValueError:
            print("Invalid integer.")
            sys.exit(1)
    elif mode == 'from-roman':
        print(roman_to_int(value.upper()))
    else:
        print("Unknown mode.")
        sys.exit(1)

if __name__ == "__main__":
    main()
